/// </summary>
/// <param name = "_fieldId">The Id of the field, for which the value is being modified.</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(InventNonConformanceTable, AVAStatus):
            this.AVAStatusModifiedDateTime  = DateTimeUtil::getSystemDateTime();
            this.AVAStatusModifiedByUser    = curUserId();
            break;
    }
}
